// CAV opening pickup, v001. Native Foundry 14 Region ExecuteScript.
// A player-controlled character physically moves into the Shack region.
// GM-authoritative world/Actor document writes; no GM clicks, macros or external sockets.
if (event?.name !== 'tokenMoveIn') return;
if (game.world?.id !== 'cabin-in-the-ashen-veil' || game.version !== '14.367') return;
if (!game.user?.isGM || game.users.activeGM?.id !== game.user.id) return;
const SCENE='CAVEXT01Yard0001';
const REGION='CAV01R0000000006';
const ITEM_ID='CAVOARSPOND00001';
const SCOPE='dicebox-campaign-helper';
const STATE_KEY='cavOarsPickup';
if (scene?.id !== SCENE || region?.id !== REGION) return;
const candidate=event.data?.token?.document ?? event.data?.token;
const token=scene.tokens.get(candidate?.id ?? event.data?.tokenId);
if (!token || token.hidden || token.actorId == null) return;
const actor=token.actor;
if (!actor || actor.type!=='character') return;
const moverId=event.userId ?? event.data?.userId ?? null;
const owners=game.users.contents.filter(u=>!u.isGM && u.active && actor.testUserPermission(u,'OWNER'));
const player=moverId ? owners.find(u=>u.id===moverId) : owners.length===1 ? owners[0] : null;
if (!player) return;
const source=game.items.get(ITEM_ID);
if (!source || source.uuid!==`Item.${ITEM_ID}` || source.name!=='Wooden Oars') return;
const claim=region.getFlag(SCOPE,STATE_KEY);
if (claim?.status==='done' || claim?.status==='reserved') return;
const hasReward=game.actors.contents.some(a=>a.items.contents.some(i=>
  i.getFlag?.(SCOPE,'cavPickupSourceUuid')===source.uuid &&
  i.getFlag?.(SCOPE,'cavPickupRegionUuid')===region.uuid));
if (hasReward) return; // missing ledger: stop, never blindly duplicate
const busy=globalThis.__CAV_EARLY_OARS_PENDING__ ?? (globalThis.__CAV_EARLY_OARS_PENDING__ = new Set());
if (busy.has(REGION)) return;
busy.add(REGION);
try {
  await region.setFlag(SCOPE, STATE_KEY, {status:'reserved',actorId:actor.id,tokenId:token.id,sourceUuid:source.uuid});
  const reward=source.toObject();delete reward._id;
  reward.flags={...reward.flags,[SCOPE]:{
    ...reward.flags?.[SCOPE],cavPickupSourceUuid:source.uuid,cavPickupRegionUuid:region.uuid,
    cavFirstActPickup:'donovans_shack_freely_available'}};
  const created=await actor.createEmbeddedDocuments('Item',[reward]);
  if (created.length!==1) throw Error('Expected exactly one Oars Item');
  await region.setFlag(SCOPE,STATE_KEY,{status:'done',actorId:actor.id,tokenId:token.id,sourceUuid:source.uuid,itemId:created[0].id});
  await ChatMessage.create({speaker:{alias:'Donovan’s Shack'},
    content:'<p>A pair of well-worn wooden oars leans near the shack. You take them; they are still sturdy enough for the old rowboat.</p>',
    whisper:[player.id]});
} catch(err) {
  console.error('[CAV Early Oars] Reward outcome requires inspection; reserved claim retained.',err);
} finally {busy.delete(REGION)}

// CAV pond mirror pickup, v001. Native Foundry 14 Region ExecuteScript.
// A player-controlled character moves to the approved pond rowboat at the dock.
// GM-authoritative world/Actor document writes; no GM clicks, macros or external sockets.
if (!['tokenMoveIn','tokenMoveWithin'].includes(event?.name)) return;
if (game.world?.id !== 'cabin-in-the-ashen-veil' || game.version !== '14.367') return;
if (!game.user?.isGM || game.users.activeGM?.id !== game.user.id) return;
const SCENE='CAVEXT02Scene001';
const REGION='CAVROWBOATREG001';
const ITEM_ID='CAVMIRRORSUNK001';
const SCOPE='dicebox-campaign-helper';
const STATE_KEY='cavPondMirrorPickup';
if (scene?.id !== SCENE || region?.id !== REGION) return;
const candidate=event.data?.token?.document ?? event.data?.token;
const token=scene.tokens.get(candidate?.id ?? event.data?.tokenId);
if (!token || token.hidden || token.actorId == null) return;
const actor=token.actor;
if (!actor || actor.type!=='character') return;
const moverId=event.userId ?? event.data?.userId ?? null;
const owners=game.users.contents.filter(u=>!u.isGM && u.active && actor.testUserPermission(u,'OWNER'));
const player=moverId ? owners.find(u=>u.id===moverId) : owners.length===1 ? owners[0] : null;
if (!player) return;
const ownsOars=actor.items.contents.some(i=>i.getFlag?.(SCOPE,'cavPickupSourceUuid')==='Item.CAVOARSPOND00001' ||
  (i.name==='Wooden Oars' && i.getFlag?.(SCOPE,'cavFirstActPickup')==='donovans_shack_freely_available'));
if (!ownsOars) return;
const source=game.items.get(ITEM_ID);
if (!source || source.uuid!==`Item.${ITEM_ID}` || source.name!=='Ornate Mirror') return;
const claim=region.getFlag(SCOPE,STATE_KEY);
if (claim?.status==='done' || claim?.status==='reserved') return;
const hasReward=game.actors.contents.some(a=>a.items.contents.some(i=>
  i.getFlag?.(SCOPE,'cavPickupSourceUuid')===source.uuid &&
  i.getFlag?.(SCOPE,'cavPickupRegionUuid')===region.uuid));
if (hasReward) return; // missing ledger: stop, never blindly duplicate
const busy=globalThis.__CAV_EARLY_MIRROR_PENDING__ ?? (globalThis.__CAV_EARLY_MIRROR_PENDING__ = new Set());
if (busy.has(REGION)) return;
busy.add(REGION);
try {
  await region.setFlag(SCOPE, STATE_KEY, {status:'reserved',actorId:actor.id,tokenId:token.id,sourceUuid:source.uuid});
  const reward=source.toObject();delete reward._id;
  reward.flags={...reward.flags,[SCOPE]:{
    ...reward.flags?.[SCOPE],cavPickupSourceUuid:source.uuid,cavPickupRegionUuid:region.uuid,
    cavFirstActPickup:'pond_full_sunken_rowboat_retrieval'}};
  const created=await actor.createEmbeddedDocuments('Item',[reward]);
  if (created.length!==1) throw Error('Expected exactly one Oars Item');
  await region.setFlag(SCOPE,STATE_KEY,{status:'done',actorId:actor.id,tokenId:token.id,sourceUuid:source.uuid,itemId:created[0].id});
  await ChatMessage.create({speaker:{alias:'The Old Rowboat'},
    content:'<p>With the wooden oars, you reach an older rowboat beneath the water and retrieve an ornate mirror from the wreck.</p>',
    whisper:[player.id]});
} catch(err) {
  console.error('[CAV Pond Mirror] Reward outcome requires inspection; reserved claim retained.',err);
} finally {busy.delete(REGION)}

// CAV H-G06 FIREPLACE — PLAYER CLICK BEHAVIOR (Foundry 14.367), v001
// Embedded Region Execute Script. No Macro document, no player Macro permission.
// Execute Script behavior fires this source on: behaviorActivated, behaviorViewed,
// behaviorUnviewed, behaviorDeactivated. Click events are registered on the canvas.
// All Foundry document mutations are performed only on the elected active GM.
const KEY = "__CAV_HG06_FIREPLACE_SCRIPT_V001__";
const CHANNEL = "module.dicebox-campaign-helper";
const PROTOCOL = "cav.hg06.fireplace.v001";
const SCENE_ID = "CAVHG06GreatRoom";
const REGION_ID = "G0HM92QQtEfyZcFi";
const LIGHT_ID = "fuWonmPqjJX2SIVG";
const current = globalThis[KEY] ?? (globalThis[KEY] = {
  socketHandler: null, clickHandler: null, clickStage: null,
  modalOpen: false, busy: false, seen: new Map()
});
const evt = event?.name ?? "";
const removeClick = () => {
  if (current.clickHandler && current.clickStage) {
    current.clickStage.off("pointertap", current.clickHandler);
  }
  current.clickHandler = null;
  current.clickStage = null;
};
if (evt === "behaviorUnviewed" || evt === "behaviorDeactivated") {
  removeClick();
  if (evt === "behaviorDeactivated" && current.socketHandler) {
    game.socket.off(CHANNEL, current.socketHandler);
    current.socketHandler = null;
    delete globalThis[KEY];
  }
  return;
}
if (!["behaviorActivated", "behaviorViewed"].includes(evt)) return;
if (!game.ready || game.world?.id !== "cabin-in-the-ashen-veil") return;
if (scene?.id !== SCENE_ID || region?.id !== REGION_ID) return;
if (!game.modules.get("dicebox-campaign-helper")?.active) return;

const getScene = () => game.scenes.get(SCENE_ID);
const isActiveGM = () => Boolean(game.user?.isGM && game.users.activeGM?.id === game.user.id);
const hasTinderbox = actor => Boolean(actor?.items?.contents?.some(item =>
  /^tinder[\s-]*box(?:\b|$)/i.test(item.name?.trim() ?? "") &&
  Number(item.system?.quantity ?? 1) > 0
));
const actorForToken = (tokenId, user) => {
  const t = getScene()?.tokens.get(tokenId);
  const a = t?.actor;
  if (!a || a.type !== "character" || !a.testUserPermission(user, "OWNER")) return null;
  return a;
};
// The GM socket listener persists while visiting another Scene and is installed
// whenever this behavior is activated/viewed in the currently open world.
if (!current.socketHandler) {
  current.socketHandler = async (data) => {
    if (!data || data.protocol !== PROTOCOL || data.kind !== "request" || !isActiveGM()) return;
    if (current.busy) return;
    if (typeof data.nonce !== "string" || !/^[A-Za-z0-9]{8,40}$/.test(data.nonce)) return;
    if (data.sceneId !== SCENE_ID || data.regionId !== REGION_ID ||
        data.lightId !== LIGHT_ID || !["light", "extinguish"].includes(data.action)) return;
    const user = game.users.get(data.userId);
    if (!user?.active || !data.tokenId || typeof data.tokenId !== "string") return;
    const actor = actorForToken(data.tokenId, user);
    if (!actor) return;
    const key = data.userId + ":" + data.nonce;
    if (current.seen.has(key)) return;
    current.seen.set(key, Date.now());
    if (current.seen.size > 80) {
      const oldest = current.seen.keys().next().value;
      current.seen.delete(oldest);
    }
    const reply = (success, message, nowLit) =>
      game.socket.emit(CHANNEL, {
        protocol: PROTOCOL, kind: "result", nonce: data.nonce,
        userId: user.id, success, message, nowLit
      });
    const light = getScene()?.lights.get(LIGHT_ID);
    if (!light) return void reply(false, "The fireplace light is unavailable.", null);
    const lit = !light.hidden;
    if (data.action === "light" && lit) return void reply(false, "The fireplace is already lit.", true);
    if (data.action === "extinguish" && !lit) return void reply(false, "The fireplace is already out.", false);
    // Lighting requires a carried, nonzero-quantity Tinderbox. Not consumed.
    if (data.action === "light" && !hasTinderbox(actor)) {
      return void reply(false, "Requires Tinderbox in your character's inventory.", false);
    }
    current.busy = true;
    try {
      await light.update({hidden: data.action === "extinguish"});
      const live = getScene()?.lights.get(LIGHT_ID);
      const nowLit = live ? !live.hidden : null;
      if (nowLit !== (data.action === "light")) {
        await reply(false, "The fireplace state could not be verified.", nowLit);
      } else {
        await reply(true, nowLit ? "You light the old wood. The hearth catches fire." :
          "You put out the fireplace.", nowLit);
      }
    } catch (err) {
      console.error("[CAV Fireplace] Light toggle failed", err);
      await reply(false, "The fire could not be changed. Ask the GM to check the light.", !light.hidden);
    } finally {
      current.busy = false;
    }
  };
  game.socket.on(CHANNEL, current.socketHandler);
}
// No click registration when this Scene isn't currently viewed.
if (canvas.scene?.id !== SCENE_ID || !canvas.stage) return;
if (current.clickHandler && current.clickStage !== canvas.stage) removeClick();
if (current.clickHandler) return;
current.clickHandler = async (pointer) => {
  if (current.modalOpen || canvas.scene?.id !== SCENE_ID) return;
  const r = getScene()?.regions.get(REGION_ID);
  const light = getScene()?.lights.get(LIGHT_ID);
  if (!r || !light || !pointer?.global) return;
  const pos = canvas.stage.toLocal(pointer.global);
  if (!Number.isFinite(pos.x) || !Number.isFinite(pos.y)) return;
  // Geometric hit-test is independent of Region-outline visibility, token
  // vision, fog and which canvas tool/layer is active.
  if (!r.testPoint({x:pos.x, y:pos.y, elevation:0})) return;
  current.modalOpen = true;
  try {
    const lit = !light.hidden;
    const description = lit ?
      "The old wood is burning in the fireplace." :
      "The wood in the fireplace is old and dry, but it should still burn.";
    const question = lit ?
      "Do you wish to put out the fire?" :
      "Do you wish to light the fire?";
    const requirement = lit ? "" :
      '<p style="font-size:0.85em"><strong>Required: Tinderbox</strong></p>';
    const approved = await foundry.applications.api.DialogV2.confirm({
      window: {title: "Great Room Fireplace"},
      content: "<p>" + description + "</p><p>" + question + "</p>" + requirement,
      yes: {label: lit ? "Put Out Fire" : "Light Fire"},
      no: {label: "Cancel"}
    });
    if (!approved) return;
    // The acting character must have a Token in this same Scene. Controlled
    // owned token takes priority; fall back to the user's assigned character.
    const user = game.user;
    const tokens = getScene().tokens.contents.filter(t =>
      t.actor?.type === "character" && t.actor.testUserPermission(user, "OWNER"));
    let token = canvas.tokens.controlled.map(t => t.document).find(t =>
      tokens.some(candidate => candidate.id === t.id));
    token ??= tokens.find(t => t.actor?.id === user.character?.id);
    token ??= tokens.length === 1 ? tokens[0] : null;
    if (!token) {
      ui.notifications.warn("Select your character token in this Scene to use the fireplace.");
      return;
    }
    if (!lit && !hasTinderbox(token.actor)) {
      ui.notifications.warn("Required: Tinderbox in your character's inventory.");
      return;
    }
    const nonce = foundry.utils.randomID(16);
    const resultHandler = (msg) => {
      if (msg?.protocol !== PROTOCOL || msg?.kind !== "result" ||
          msg.userId !== user.id || msg.nonce !== nonce) return;
      game.socket.off(CHANNEL, resultHandler);
      ui.notifications[msg.success ? "info" : "warn"](msg.message);
    };
    game.socket.on(CHANNEL, resultHandler);
    await game.socket.emit(CHANNEL, {
      protocol: PROTOCOL, kind:"request", nonce, userId:user.id,
      sceneId:SCENE_ID, regionId:REGION_ID, lightId:LIGHT_ID,
      tokenId:token.id, action:lit ? "extinguish" : "light"
    });
  } catch(err) {
    console.error("[CAV Fireplace] Click interaction failed", err);
    ui.notifications.warn("The fireplace interaction could not open.");
  } finally {
    current.modalOpen = false;
  }
};
current.clickStage = canvas.stage;
current.clickStage.on("pointertap", current.clickHandler);
console.info("[CAV Fireplace] Region click behavior registered for user", game.user.id);

// H-U07 Dahlia's Studio - mirror socket and paired vanity key discovery (v001)
// Native Foundry v14 ExecuteScript, dispatched only by a character's token movement.
// Authority: elected active GM only. The player does not need GM rights or a Macro.
if (!['tokenMoveIn', 'tokenMoveWithin'].includes(event?.name)) return;
if (!game.ready || game.world?.id!=='cabin-in-the-ashen-veil' || game.version!=='14.367') return;
if (!game.user?.isGM || game.users.activeGM?.id!==game.user.id) return;
const SCENE_ID='CAVHU07Scene0001', REGION_ID='CAVVANITYREG0001';
const SCOPE='dicebox-campaign-helper', LEDGER='cavVanityKeysClaim';
const MIRROR='Item.CAVMIRRORSUNK001';
const REWARDS=['Item.CAVBRASSKEYVAN01','Item.CAVCARRIAGEKEY01'];
if (scene?.id!==SCENE_ID || region?.id!==REGION_ID) return;
const candidate=event.data?.token?.document??event.data?.token;
const token=scene.tokens.get(candidate?.id??event.data?.tokenId);
if (!token || token.hidden || !token.actorId) return;
const actor=token.actor;
if (!actor || actor.type!=='character') return;
const owners=game.users.contents.filter(u=>!u.isGM && u.active && actor.testUserPermission(u,'OWNER'));
const eventUserId=event.userId??event.data?.userId??null;
const player=eventUserId ? owners.find(u=>u.id===eventUserId) : owners.length===1 ? owners[0] : null;
if (!player) return;
const hasMirror=actor.items.contents.some(i=>i.getFlag?.(SCOPE,'cavPickupSourceUuid')===MIRROR &&
  i.getFlag?.(SCOPE,'cavPickupRegionUuid')==='Scene.CAVEXT02Scene001.Region.CAVROWBOATREG001');
if (!hasMirror) return;
const existing=region.getFlag(SCOPE,LEDGER);
if (existing?.status==='done' || existing?.status==='reserved') return;
const alreadyGranted=game.actors.contents.some(a=>a.items.contents.some(i=>
  REWARDS.includes(i.getFlag?.(SCOPE,'cavVanityRewardSourceUuid')) &&
  i.getFlag?.(SCOPE,'cavVanityRewardRegionUuid')===region.uuid));
if (alreadyGranted) return; // lost ledger: reconcile existing Item, don't duplicate
const sources=REWARDS.map(uuid=>game.items.get(uuid.slice(5)));
if (sources.some((x,i)=>!x || x.uuid!==REWARDS[i])) return;
if (sources[0].name!=='Brass Tiny Key #1' || sources[1].name!=='Carriage Key') return;
const BUSY='__CAV_HU07_VANITY_REWARD_BUSY__';
const pending=globalThis[BUSY]??(globalThis[BUSY]=new Set());
if (pending.has(REGION_ID)) return;
pending.add(REGION_ID);
try {
  await region.setFlag(SCOPE,LEDGER,{status:'reserved',actorId:actor.id,tokenId:token.id,mirrorUuid:MIRROR,rewardUuids:REWARDS});
  const docs=sources.map(item=>{
    const value=item.toObject();delete value._id;
    value.flags={...value.flags,[SCOPE]:{...value.flags?.[SCOPE],cavVanityRewardSourceUuid:item.uuid,
      cavVanityRewardRegionUuid:region.uuid,cavFirstActReward:'art_studio_vanity_after_mirror'}};
    return value;
  });
  const created=await actor.createEmbeddedDocuments('Item',docs);
  if(created.length!==2)throw Error('Vanity reward partial response; claim reservation requires review');
  await region.setFlag(SCOPE,LEDGER,{status:'done',actorId:actor.id,tokenId:token.id,mirrorUuid:MIRROR,
    rewardUuids:REWARDS,embeddedItemIds:created.map(i=>i.id)});
  try {await ChatMessage.create({speaker:{alias:'Dahlia Vanity'},
    content:'<p>The ornate mirror settles into the old vanity frame. Two hidden drawers ease open, revealing a tiny brass key and an iron carriage key.</p>',whisper:[player.id]});}
  catch(chatErr){console.warn('[CAV Vanity] Keys granted, but private narrative delivery failed',chatErr)}
} catch(err){console.error('[CAV Vanity] Outcome uncertain, reserved claim preserved for recovery',err)}
finally {pending.delete(REGION_ID)}
